--
-- Name: audit_session_login(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."audit_session_login"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_email text;
BEGIN
    SELECT email INTO v_email FROM public.profiles WHERE id = NEW.profile_id;
    INSERT INTO public.login_events (profile_id, email, event, ip, user_agent)
    VALUES (NEW.profile_id, v_email, 'login_success', NEW.ip, NEW.user_agent);
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."audit_session_login"() OWNER TO "postgres";

--
-- Name: audit_session_revoke(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."audit_session_revoke"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_email text;
    v_event text;
BEGIN
    IF OLD.revoked_at IS NULL AND NEW.revoked_at IS NOT NULL THEN
        SELECT email INTO v_email FROM public.profiles WHERE id = NEW.profile_id;
        v_event := CASE WHEN NEW.revoked_reason = 'logout' THEN 'logout' ELSE 'session_revoked' END;
        INSERT INTO public.login_events (profile_id, email, event, ip, user_agent)
        VALUES (NEW.profile_id, v_email, v_event, NEW.ip, NEW.user_agent);
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."audit_session_revoke"() OWNER TO "postgres";

