--
-- Name: cluster_questions("uuid"[], "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."cluster_questions"("question_ids" "uuid"[], "cluster_uuid" "uuid" DEFAULT "gen_random_uuid"()) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Check if user is admin
  IF NOT EXISTS (
    SELECT 1 FROM public.leadership l
    JOIN public.tenures t ON l.tenure_id = t.id
    JOIN public.leadership_positions lp ON l.position_id = lp.id
    WHERE l.profile_id = auth.uid()
    AND t.is_active = true
    AND lp.category IN ('PRESIDENT', 'CENTRAL')
  ) THEN
    RAISE EXCEPTION 'Insufficient permissions';
  END IF;

  UPDATE public.event_questions
  SET cluster_id = cluster_uuid, updated_at = NOW()
  WHERE id = ANY(question_ids);

  RETURN cluster_uuid;
END;
$$;


ALTER FUNCTION "public"."cluster_questions"("question_ids" "uuid"[], "cluster_uuid" "uuid") OWNER TO "postgres";

--
-- Name: enforce_position_privilege_rules(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."enforce_position_privilege_rules"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_tags text[];
BEGIN
    SELECT array_agg(DISTINCT privilege) INTO v_tags
    FROM public.position_privileges
    WHERE position_id = NEW.position_id
      AND id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid);
    v_tags := COALESCE(v_tags, ARRAY[]::text[]) || NEW.privilege;

    IF ('EXCO' = ANY (v_tags)) AND ('LEVEL' = ANY (v_tags)) THEN
        RAISE EXCEPTION 'A position cannot hold both EXCO and LEVEL privileges.';
    END IF;

    IF ('PRESIDENT' = ANY (v_tags)) AND (array_length(array(
            SELECT DISTINCT unnest(v_tags) EXCEPT SELECT 'PRESIDENT'), 1) > 0) THEN
        RAISE EXCEPTION 'PRESIDENT is exclusive and cannot be combined with other privileges.';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_position_privilege_rules"() OWNER TO "postgres";

--
-- Name: enforce_single_unit_membership(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."enforce_single_unit_membership"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_type text;
BEGIN
    SELECT type INTO v_type FROM public.units WHERE id = NEW.unit_id;

    IF v_type = 'UNIT' THEN
        IF EXISTS (
            SELECT 1
            FROM public.membership_units mu
            JOIN public.units u ON u.id = mu.unit_id
            WHERE mu.profile_id = NEW.profile_id
              AND mu.tenure_id = NEW.tenure_id
              AND u.type = 'UNIT'
              AND mu.id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
        ) THEN
            RAISE EXCEPTION 'Member already belongs to a unit for this tenure (only one unit allowed).';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_single_unit_membership"() OWNER TO "postgres";

--
-- Name: generate_order_ref(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."generate_order_ref"() RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    ref TEXT;
    exists BOOLEAN;
BEGIN
    LOOP
        ref := UPPER(SUBSTRING(encode(gen_random_bytes(3), 'hex') FROM 1 FOR 6));
        SELECT COUNT(*) > 0 INTO exists FROM rw_orders WHERE order_ref = ref;
        EXIT WHEN NOT exists;
    END LOOP;
    RETURN ref;
END;
$$;


ALTER FUNCTION "public"."generate_order_ref"() OWNER TO "postgres";

