--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  extracted_first_name text;
  extracted_last_name text;
BEGIN
  -- Attempt to get names from metadata. 
  -- If you sent { data: { first_name: '...', last_name: '...' } } it uses that.
  -- If you sent { data: { full_name: 'John Doe' } }, it splits it.
  
  extracted_first_name := COALESCE(
    NEW.raw_user_meta_data->>'first_name', 
    split_part(NEW.raw_user_meta_data->>'full_name', ' ', 1), 
    'New' -- Fallback
  );
  
  extracted_last_name := COALESCE(
    NEW.raw_user_meta_data->>'last_name', 
    substr(
      NEW.raw_user_meta_data->>'full_name', 
      length(split_part(NEW.raw_user_meta_data->>'full_name', ' ', 1)) + 2
    ), 
    'Member' -- Fallback
  );

  -- Insert into profiles
  INSERT INTO public.profiles (id, email, first_name, last_name, created_at, updated_at)
  VALUES (
    NEW.id, 
    NEW.email, 
    extracted_first_name, 
    extracted_last_name,
    NOW(), 
    NOW()
  )
  -- CRITICAL: If your app code creates the profile manually immediately after signup,
  -- this prevents a "Duplicate Key" error by doing nothing if the row exists.
  ON CONFLICT (id) DO UPDATE SET
    email = EXCLUDED.email;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";

