--
-- Name: rcf_compute_level(integer, boolean, "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rcf_compute_level"("p_entry_year" integer, "p_is_foundation" boolean, "p_session" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
    SELECT CASE
        WHEN p_is_foundation THEN 'PDS/UABS'
        WHEN p_entry_year IS NULL OR p_session IS NULL OR p_session !~ '^\d{4}' THEN NULL
        WHEN (left(p_session, 4)::int - p_entry_year + 1) < 1 THEN 'Pre-100'
        WHEN (left(p_session, 4)::int - p_entry_year + 1) > 5 THEN 'Alumni'
        ELSE ((left(p_session, 4)::int - p_entry_year + 1) * 100)::text || ' Level'
    END;
$$;


ALTER FUNCTION "public"."rcf_compute_level"("p_entry_year" integer, "p_is_foundation" boolean, "p_session" "text") OWNER TO "postgres";

--
-- Name: rcf_login_context("text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rcf_login_context"("p_email" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_profile_id uuid;
    v_email      text;
    v_login      public.profile_login%ROWTYPE;
BEGIN
    SELECT id, email INTO v_profile_id, v_email
    FROM public.profiles WHERE lower(email) = lower(p_email) LIMIT 1;
    IF v_profile_id IS NULL THEN
        RETURN NULL;
    END IF;

    SELECT * INTO v_login FROM public.profile_login WHERE profile_id = v_profile_id;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    RETURN jsonb_build_object(
        'profileId', v_profile_id,
        'email', v_email,
        'loginId', v_login.id,
        'passwordHash', v_login.password_hash,
        'isActive', v_login.is_active,
        'failedAttempts', v_login.failed_attempts,
        'lockedUntil', v_login.locked_until,
        'context', public.rcf_profile_context(v_profile_id)
    );
END;
$$;


ALTER FUNCTION "public"."rcf_login_context"("p_email" "text") OWNER TO "postgres";

--
-- Name: rcf_profile_context("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rcf_profile_context"("p_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_tenure_id uuid;
    v_session   text;
    v_result    jsonb;
BEGIN
    SELECT id, session INTO v_tenure_id, v_session
    FROM public.tenures WHERE is_active LIMIT 1;

    SELECT jsonb_build_object(
        'profile', jsonb_build_object(
            'id', p.id,
            'firstName', p.first_name,
            'lastName', p.last_name,
            'middleName', p.middle_name,
            'email', p.email,
            'phoneNumber', p.phone_number,
            'gender', p.gender,
            'avatarUrl', p.avatar_url,
            'avatarPublicId', p.avatar_public_id
        ),
        'location', jsonb_build_object(
            'schoolAddress', p.school_address,
            'homeAddress', p.home_address,
            'residentialZone', rz.name
        ),
        'academics', jsonb_build_object(
            'matricNumber', p.matric_number,
            'department', p.department,
            'faculty', p.faculty,
            'entryYear', cs.entry_year,
            'family', cs.family_name,
            'currentLevel', public.rcf_compute_level(cs.entry_year, COALESCE(cs.is_foundation, false), v_session)
        ),
        'classSet', CASE WHEN cs.id IS NULL THEN NULL ELSE jsonb_build_object(
            'id', cs.id, 'entryYear', cs.entry_year, 'familyName', cs.family_name,
            'isFoundation', COALESCE(cs.is_foundation, false),
            'currentLevel', public.rcf_compute_level(cs.entry_year, COALESCE(cs.is_foundation, false), v_session)
        ) END,
        'roles', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'title', lp.title, 'scope', lp.category,
                'contextName', COALESCE(u.name, lcs.family_name, lrz.name)))
            FROM public.leadership l
            JOIN public.leadership_positions lp ON lp.id = l.position_id
            LEFT JOIN public.units u ON u.id = l.unit_id
            LEFT JOIN public.class_sets lcs ON lcs.id = l.class_set_id
            LEFT JOIN public.residential_zones lrz ON lrz.id = l.residential_zone_id
            WHERE l.profile_id = p.id AND (v_tenure_id IS NULL OR l.tenure_id = v_tenure_id)
        ), '[]'::jsonb),
        'leadership', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'leadershipId', l.id, 'positionId', l.position_id,
                'title', lp.title, 'alias', lp.alias, 'slug', lp.slug, 'category', lp.category,
                'isDefault', lp.is_default, 'unitId', l.unit_id, 'unitName', u.name,
                'classSetId', l.class_set_id, 'residentialZoneId', l.residential_zone_id,
                'tenureId', l.tenure_id,
                'privileges', COALESCE((                                        -- 0006: per-position privilege tags
                    SELECT jsonb_agg(jsonb_build_object('tag', pp.privilege, 'scope', pp.scope))
                    FROM public.position_privileges pp WHERE pp.position_id = l.position_id
                ), '[]'::jsonb)))
            FROM public.leadership l
            JOIN public.leadership_positions lp ON lp.id = l.position_id
            LEFT JOIN public.units u ON u.id = l.unit_id
            WHERE l.profile_id = p.id AND (v_tenure_id IS NULL OR l.tenure_id = v_tenure_id)
        ), '[]'::jsonb),
        'unit', (
            SELECT jsonb_build_object('id', u.id, 'name', u.name, 'role', mu.role)
            FROM public.membership_units mu
            JOIN public.units u ON u.id = mu.unit_id
            WHERE mu.profile_id = p.id AND u.type = 'UNIT'
              AND (v_tenure_id IS NULL OR mu.tenure_id = v_tenure_id)
            LIMIT 1
        ),
        'teams', COALESCE((
            SELECT jsonb_agg(jsonb_build_object('id', u.id, 'name', u.name, 'role', mu.role))
            FROM public.membership_units mu
            JOIN public.units u ON u.id = mu.unit_id
            WHERE mu.profile_id = p.id AND u.type = 'TEAM'
              AND (v_tenure_id IS NULL OR mu.tenure_id = v_tenure_id)
        ), '[]'::jsonb),
        -- 0006: admin flags are now derived from PRIVILEGE TAGS, not category/is_default.
        'isSysAdmin', EXISTS (                                                  -- 0006
            SELECT 1 FROM public.leadership l
            JOIN public.position_privileges pp ON pp.position_id = l.position_id
            WHERE l.profile_id = p.id AND (v_tenure_id IS NULL OR l.tenure_id = v_tenure_id)
              AND pp.privilege = 'SYSADMIN'),
        'isPresident', EXISTS (                                                 -- 0006
            SELECT 1 FROM public.leadership l
            JOIN public.position_privileges pp ON pp.position_id = l.position_id
            WHERE l.profile_id = p.id AND (v_tenure_id IS NULL OR l.tenure_id = v_tenure_id)
              AND pp.privilege = 'PRESIDENT'),
        'isVpAdmin', EXISTS (
            SELECT 1 FROM public.leadership l
            JOIN public.leadership_positions lp ON lp.id = l.position_id
            WHERE l.profile_id = p.id AND (v_tenure_id IS NULL OR l.tenure_id = v_tenure_id)
              AND lp.title = 'Vice President Administration'),
        -- READ-bypass tier: SysAdmin, President, or VP Admin see everything (write is
        -- gated separately in app resolvers — President is globally write-blocked).
        'isAdmin', EXISTS (                                                     -- 0006
            SELECT 1 FROM public.leadership l
            LEFT JOIN public.position_privileges pp ON pp.position_id = l.position_id
            JOIN public.leadership_positions lp ON lp.id = l.position_id
            WHERE l.profile_id = p.id AND (v_tenure_id IS NULL OR l.tenure_id = v_tenure_id)
              AND (pp.privilege IN ('SYSADMIN','PRESIDENT')
                   OR lp.title = 'Vice President Administration'))
    )
    INTO v_result
    FROM public.profiles p
    LEFT JOIN public.residential_zones rz ON rz.id = p.residential_zone_id
    LEFT JOIN public.class_sets cs ON cs.id = p.class_set_id
    WHERE p.id = p_profile_id;

    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."rcf_profile_context"("p_profile_id" "uuid") OWNER TO "postgres";

--
-- Name: search_members_detailed("text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."search_members_detailed"("query_text" "text") RETURNS SETOF json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  current_session_year INT;
BEGIN
  -- 1. Get the start year of the ACTIVE session (e.g., "2025" from "2025/2026")
  -- If no tenure is active, fallback to the current actual year.
  SELECT COALESCE(
    (SELECT SPLIT_PART(session, '/', 1)::INT FROM public.tenures WHERE is_active = true LIMIT 1),
    EXTRACT(YEAR FROM CURRENT_DATE)::INT
  ) INTO current_session_year;

  RETURN QUERY
  SELECT 
    json_build_object(
      'id', p.id,
      'first_name', p.first_name,
      'last_name', p.last_name,
      'email', u.email,
      'phone_number', p.phone_number,
      'avatar_url', p.avatar_url,
      
      -- We still keep department as it helps identification, but you can ignore it in UI if you want
      'department', p.department, 

      -- CALCULATED LEVEL (The requested feature)
      'level', CASE 
        WHEN cs.entry_year IS NULL THEN 'N/A'
        WHEN ((current_session_year - cs.entry_year) + 1) * 100 > 500 THEN 'Alumni'
        ELSE (((current_session_year - cs.entry_year) + 1) * 100)::text || ' Level'
      END,

      -- UNITS
      'units', COALESCE(
        (
          SELECT json_agg(un.name)
          FROM public.membership_units mu
          JOIN public.units un ON mu.unit_id = un.id
          WHERE mu.profile_id = p.id AND un.type = 'UNIT'
        ), 
        '[]'::json
      ),

      -- TEAMS
      'teams', COALESCE(
        (
          SELECT json_agg(un.name)
          FROM public.membership_units mu
          JOIN public.units un ON mu.unit_id = un.id
          WHERE mu.profile_id = p.id AND un.type = 'TEAM'
        ), 
        '[]'::json
      ),

      -- LEADERSHIP
      'leadership', COALESCE(
        (
          SELECT json_agg(json_build_object(
            'title', lp.title,
            'category', lp.category
          ))
          FROM public.leadership l
          JOIN public.leadership_positions lp ON l.position_id = lp.id
          JOIN public.tenures t ON l.tenure_id = t.id
          WHERE l.profile_id = p.id AND t.is_active = true
        ), 
        '[]'::json
      )
    )
  FROM 
    public.profiles p
  JOIN 
    auth.users u ON p.id = u.id
  LEFT JOIN
    public.class_sets cs ON p.class_set_id = cs.id -- Join to get Entry Year
  WHERE 
    u.email ILIKE '%' || query_text || '%'
    OR p.first_name ILIKE '%' || query_text || '%'
    OR p.last_name ILIKE '%' || query_text || '%'
    OR p.phone_number ILIKE '%' || query_text || '%';
END;
$$;


ALTER FUNCTION "public"."search_members_detailed"("query_text" "text") OWNER TO "postgres";

