--
-- Name: event_questions_with_details; Type: VIEW; Schema: public; Owner: postgres
--

CREATE OR REPLACE VIEW "public"."event_questions_with_details" AS
 SELECT "eq"."id",
    "eq"."event_id",
    "eq"."question_text",
    "eq"."scripture_reference",
    "eq"."asked_by_profile_id",
    "eq"."asker_name",
    "eq"."answer_text",
    "eq"."answered_by_profile_id",
    "eq"."answered_at",
    "eq"."status",
    "eq"."is_pinned",
    "eq"."cluster_id",
    "eq"."parent_question_id",
    "eq"."created_at",
    "eq"."updated_at",
    "eq"."search_vector",
    (("p"."first_name" || ' '::"text") || "p"."last_name") AS "author_full_name",
    (("ap"."first_name" || ' '::"text") || "ap"."last_name") AS "answerer_full_name",
    "e"."title" AS "event_title",
    "e"."slug" AS "event_slug",
    ( SELECT "count"(*) AS "count"
           FROM "public"."question_flags" "qf"
          WHERE (("qf"."question_id" = "eq"."id") AND ("qf"."is_resolved" = false))) AS "active_flags_count"
   FROM ((("public"."event_questions" "eq"
     LEFT JOIN "public"."profiles" "p" ON (("eq"."asked_by_profile_id" = "p"."id")))
     LEFT JOIN "public"."profiles" "ap" ON (("eq"."answered_by_profile_id" = "ap"."id")))
     JOIN "public"."events" "e" ON (("eq"."event_id" = "e"."id")));


ALTER VIEW "public"."event_questions_with_details" OWNER TO "postgres";

--
-- Name: search_questions("text", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."search_questions"("search_term" "text", "event_id_filter" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF "public"."event_questions_with_details"
    LANGUAGE "sql" STABLE
    AS $$
  SELECT * FROM public.event_questions_with_details
  WHERE
    (event_id_filter IS NULL OR event_id = event_id_filter)
    AND (
      search_vector @@ plainto_tsquery('english', search_term)
      OR question_text ILIKE '%' || search_term || '%'
      OR scripture_reference ILIKE '%' || search_term || '%'
    )
    AND status IN ('visible', 'answered')
  ORDER BY
    ts_rank(search_vector, plainto_tsquery('english', search_term)) DESC,
    created_at DESC;
$$;


ALTER FUNCTION "public"."search_questions"("search_term" "text", "event_id_filter" "uuid") OWNER TO "postgres";

--
-- Name: set_orders_in_production(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."set_orders_in_production"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    UPDATE rw_orders
    SET status = 'in_production'
    WHERE id = NEW.order_id
      AND status NOT IN ('in_production', 'ready', 'delivered', 'cancelled');
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_orders_in_production"() OWNER TO "postgres";

--
-- Name: set_orders_ready_on_verdict(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."set_orders_ready_on_verdict"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF NEW.status = 'ready' AND OLD.status <> 'ready' THEN
        UPDATE rw_orders
        SET status = 'ready'
        WHERE id IN (
            SELECT order_id FROM rw_verdict_orders WHERE verdict_id = NEW.id
        )
        AND status = 'in_production';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_orders_ready_on_verdict"() OWNER TO "postgres";

