--
-- Name: sync_email_changes(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."sync_email_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
BEGIN
  -- Update the profile email when auth email changes
  UPDATE public.profiles
  SET email = NEW.email,
      updated_at = NOW()
  WHERE id = NEW.id;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_email_changes"() OWNER TO "postgres";

--
-- Name: sync_order_amount_paid(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."sync_order_amount_paid"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    UPDATE rw_orders
    SET amount_paid = (
        SELECT COALESCE(SUM(amount_confirmed), 0)
        FROM rw_payments
        WHERE order_id = COALESCE(NEW.order_id, OLD.order_id)
          AND status = 'approved'
    )
    WHERE id = COALESCE(NEW.order_id, OLD.order_id);
    RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."sync_order_amount_paid"() OWNER TO "postgres";

--
-- Name: toggle_question_visibility("uuid", "public"."question_status"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."toggle_question_visibility"("question_id" "uuid", "new_status" "public"."question_status") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Check if user is admin
  IF NOT EXISTS (
    SELECT 1 FROM public.leadership l
    JOIN public.tenures t ON l.tenure_id = t.id
    JOIN public.leadership_positions lp ON l.position_id = lp.id
    WHERE l.profile_id = auth.uid()
    AND t.is_active = true
    AND lp.category IN ('PRESIDENT', 'CENTRAL')
  ) THEN
    RAISE EXCEPTION 'Insufficient permissions';
  END IF;

  UPDATE public.event_questions
  SET status = new_status, updated_at = NOW()
  WHERE id = question_id;

  RETURN FOUND;
END;
$$;


ALTER FUNCTION "public"."toggle_question_visibility"("question_id" "uuid", "new_status" "public"."question_status") OWNER TO "postgres";

