CREATE OR REPLACE VIEW "public"."flagged_questions" AS
 SELECT "eq"."id",
    "eq"."question_text",
    "eq"."scripture_reference",
    "e"."title" AS "event_title",
    (("p"."first_name" || ' '::"text") || "p"."last_name") AS "author_name",
    "array_agg"("json_build_object"('reason', "qf"."reason", 'description', "qf"."description", 'flagged_at', "qf"."created_at", 'flagged_by', COALESCE((("fp"."first_name" || ' '::"text") || "fp"."last_name"), "qf"."flagged_by_name"))) AS "flags"
   FROM (((("public"."event_questions" "eq"
     JOIN "public"."events" "e" ON (("eq"."event_id" = "e"."id")))
     LEFT JOIN "public"."profiles" "p" ON (("eq"."asked_by_profile_id" = "p"."id")))
     JOIN "public"."question_flags" "qf" ON (("eq"."id" = "qf"."question_id")))
     LEFT JOIN "public"."profiles" "fp" ON (("qf"."flagged_by_profile_id" = "fp"."id")))
  WHERE ("qf"."is_resolved" = false)
  GROUP BY "eq"."id", "eq"."question_text", "eq"."scripture_reference", "e"."title", "p"."first_name", "p"."last_name";


