--

CREATE POLICY "Admin update" ON "public"."event_registrations" FOR UPDATE TO "authenticated" USING (true);


--
-- Name: event_questions Admins can manage all questions; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admins can manage all questions" ON "public"."event_questions" TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM (("public"."leadership" "l"
     JOIN "public"."tenures" "t" ON (("l"."tenure_id" = "t"."id")))
     JOIN "public"."leadership_positions" "lp" ON (("l"."position_id" = "lp"."id")))
  WHERE (("l"."profile_id" = "auth"."uid"()) AND ("t"."is_active" = true) AND ("lp"."category" = ANY (ARRAY['PRESIDENT'::"text", 'CENTRAL'::"text"]))))));


--
-- Name: question_references Admins can manage question references; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admins can manage question references" ON "public"."question_references" TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM (("public"."leadership" "l"
     JOIN "public"."tenures" "t" ON (("l"."tenure_id" = "t"."id")))
     JOIN "public"."leadership_positions" "lp" ON (("l"."position_id" = "lp"."id")))
  WHERE (("l"."profile_id" = "auth"."uid"()) AND ("t"."is_active" = true) AND ("lp"."category" = ANY (ARRAY['PRESIDENT'::"text", 'CENTRAL'::"text"]))))));


--
-- Name: question_flags Admins can view and manage flags; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admins can view and manage flags" ON "public"."question_flags" TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM (("public"."leadership" "l"
     JOIN "public"."tenures" "t" ON (("l"."tenure_id" = "t"."id")))
     JOIN "public"."leadership_positions" "lp" ON (("l"."position_id" = "lp"."id")))
  WHERE (("l"."profile_id" = "auth"."uid"()) AND ("t"."is_active" = true) AND ("lp"."category" = ANY (ARRAY['PRESIDENT'::"text", 'CENTRAL'::"text"]))))));


